tape( 'the function performs the matrix-matrix operation `op(A) * X = alpha * B` (row-major, left, lower, no-transpose, non-unit)', function test( t ) {
	var expected;
	var data;
	var out;
	var a;
	var b;

	data = rllntanu;

	a = new Float32Array( data.A );
	b = new Float32Array( data.B );

	expected = new Float32Array( data.B_out );

	out = strsm( data.order, data.side, data.uplo, data.transA, data.diag, data.M, data.N, data.alpha, a, data.lda, b, data.ldb );
	t.strictEqual( out, b, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

